using System;
using System.Collections;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Threading.Tasks;
using LastRail.Diagnostics;
using LastRail.Tests.EditMode;
using LastRail.Auth;
using LastRail.Battle;
using LastRail.Run;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
public sealed class OrdinaryRunAutomationTests {
 sealed class Storage:IAndroidKeystoreNativeStoragePort {
  AndroidKeystoreEncryptedTokenPayload saved;
  public bool IsAndroidRuntime=>true;public bool IsKeystoreAvailable=>true;public bool UsedPlayerPrefsFallback=>false;public string ProviderName=>"TEST_BASE64_NOT_ENCRYPTION";
  public AndroidKeystoreEncryptedTokenPayload Encrypt(string text)=>new AndroidKeystoreEncryptedTokenPayload(Convert.ToBase64String(Encoding.UTF8.GetBytes(text)),"test");
  public string Decrypt(AndroidKeystoreEncryptedTokenPayload p)=>Encoding.UTF8.GetString(Convert.FromBase64String(p.CipherTextBase64));
  public bool Save(AndroidKeystoreEncryptedTokenPayload p){saved=p;return true;}
  public AndroidKeystoreEncryptedTokenPayload Load()=>saved;public bool Clear(){saved=null;return true;}
 }
 static JObject Automation(OrdinaryFiveStartInput start)=>new JObject{["version"]="ordinary.run-actions.v1.20261031",["revision"]=2,["ultimateAuto"]=true,["actors"]=new JArray(start.Actors.Select(a=>new JObject{["operatorId"]=a.OperatorId,["activeCooldownRemainingTicks"]=40000000,["ultimateCharge"]=70}))};
 static object Get(object value,string name){var p=value.GetType().GetProperty(name);Assert.NotNull(p,"Missing automation consumer "+name);return p.GetValue(value);}
 static object ReadInitial(JObject response,OrdinaryFiveStartInput start){var method=typeof(OrdinaryInitializationReceipt).GetMethods().SingleOrDefault(m=>m.Name=="Validate"&&m.GetParameters().Length==3);Assert.NotNull(method,"Missing typed initialization automation output");var args=new object[]{response.ToString(),start,null};method.Invoke(null,args);return args[2];}
 [Test] public void InitialReceiptRetainsExplicitValuesAndHistoricalAbsence(){var f=FirstPlayableScalingTests.Fixture(staticSource:true);var start=OrdinaryFiveStartInput.Read(f.Start,"a",(string)f.Start["runId"]);Assert.IsNull(ReadInitial(f.Init,start));f.Init["initializationReceipt"]["ordinaryAutomation"]=Automation(start);var state=ReadInitial(f.Init,start);Assert.AreEqual(2L,Get(state,"Revision"));Assert.AreEqual(true,Get(state,"UltimateAuto"));var actor=((IEnumerable)Get(state,"Actors")).Cast<object>().First();Assert.AreEqual(40000000L,Get(actor,"ActiveCooldownRemainingTimeSpanTicks"));Assert.AreEqual(70,Get(actor,"UltimateCharge"));f.Init["initializationReceipt"]["ordinaryAutomation"]["actors"][0]["ultimateCharge"]=0;Assert.AreEqual(70,Get(actor,"UltimateCharge"));}
 [TestCase("duplicate")][TestCase("foreign")][TestCase("charge")][TestCase("cooldown")][TestCase("revision")][TestCase("missing")][TestCase("null")][TestCase("version")]
 public void InitializationRejectsMalformedOrForeignAutomation(string fault){var f=FirstPlayableScalingTests.Fixture(staticSource:true);var start=OrdinaryFiveStartInput.Read(f.Start,"a",(string)f.Start["runId"]);var a=Automation(start);f.Init["initializationReceipt"]["ordinaryAutomation"]=a;switch(fault){case "duplicate":a["actors"][1]["operatorId"]=a["actors"][0]["operatorId"].DeepClone();break;case "foreign":a["actors"][0]["operatorId"]="foreign";break;case "charge":a["actors"][0]["ultimateCharge"]=201;break;case "cooldown":a["actors"][0]["activeCooldownRemainingTicks"]=-1;break;case "revision":a["revision"]=9007199254740992L;break;case "missing":a.Remove("ultimateAuto");break;case "null":f.Init["initializationReceipt"]["ordinaryAutomation"]=null;break;case "version":a["version"]="unknown";break;}Assert.Throws<ArgumentException>(()=>OrdinaryInitializationReceipt.Validate(f.Init.ToString(),start));}
 [Test] public void NodeConsumesAutomationAndRestoredNodeKeepsOriginalOwner(){var f=OrdinaryNodeStartWireTests.Fixture();var node=f.Response["receipt"]["nodeStart"];node["snapshot"]["automation"]=Automation(f.Start);var actions=OrdinaryNodeActionsTests.Fixture(f.Start);actions["ultimateAuto"]=true;actions["stepTimeSpanTicks"]=500000;foreach(JObject a in (JArray)actions["actors"]){a["ultimateCharge"]=70;a["activeCooldownRemainingTicks"]=80;}node["snapshot"]["runtime"]["actions"]=actions;node["snapshotHash"]=BDirectAttackInput.Digest(node["snapshot"]).Substring(7);var parsed=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).NodeStart;parsed.RequireOriginal(f.Start);var state=Get(parsed,"Automation");Assert.AreEqual(true,Get(state,"UltimateAuto"));Assert.IsFalse(parsed.CanStart);var restart=new OrdinaryNodeRestart(parsed,"automation-restart",parsed.EntryMapRevision,1);var response=new JObject{["accepted"]=true,["version"]="ordinary.node-restart.v1.20261028",["requestId"]=restart.Key,["accountId"]=parsed.AccountId,["runId"]=parsed.RunId,["nodeId"]=parsed.NodeId,["status"]="RESTARTED",["revision"]=parsed.EntryMapRevision+1,["generation"]=2,["snapshot"]=parsed.Capture()["snapshot"],["snapshotHash"]=parsed.SnapshotHash};Assert.AreSame(state,Get(restart.ReadResponse(response.ToString()).Start,"Automation"));}
 static JObject Completion(string key,long revision,JObject automation)=>new JObject{["accepted"]=true,["receipt"]=new JObject{["version"]="operation.map-receipt.v1",["eventId"]=key,["revision"]=revision+1,["verificationId"]="proof",["state"]=new JObject{["version"]="operation.map-progress.v1",["traversedEdgeIds"]=new JArray(),["pendingEdgeId"]=null,["phase"]="READY",["holdIds"]=new JArray()},["ordinaryAutomation"]=automation}};
 static (OrdinaryFiveStartInput Start,BRouteCommand Command,JObject Response) NodeWithDuration(long duration,long steps,long step=500000){var f=OrdinaryNodeStartWireTests.Fixture();var node=f.Response["receipt"]["nodeStart"];var automation=Automation(f.Start);foreach(JObject a in (JArray)automation["actors"])a["activeCooldownRemainingTicks"]=duration;node["snapshot"]["automation"]=automation;var runtime=node["snapshot"]["runtime"];runtime["executionVersion"]=OrdinaryFiveCombatFactory.Version;runtime["determinism"]=new JObject{["version"]="ordinary.node-random.v1.20261029",["algorithm"]="XORSHIFT32_13_17_5_V1",["seed"]=123,["initialState"]=123};var actions=OrdinaryNodeActionsTests.Fixture(f.Start);actions["stepTimeSpanTicks"]=step;foreach(JObject a in (JArray)actions["actors"]){a["ultimateCharge"]=70;a["activeCooldownRemainingTicks"]=steps;}runtime["actions"]=actions;node["snapshotHash"]=BDirectAttackInput.Digest(node["snapshot"]).Substring(7);return f;}
 [TestCase(0L,0L)][TestCase(1L,1L)][TestCase(499999L,1L)][TestCase(500000L,1L)][TestCase(500001L,2L)][TestCase(40000000L,80L)]
 public void EntryBindsTimeSpanDurationToCeilingLogicalStepsWithoutChangingEitherSource(long duration,long steps){var f=NodeWithDuration(duration,steps);var before=f.Response.ToString();var node=BRouteCommandResult.Read(200,before,f.Command).NodeStart;Assert.AreEqual(steps,node.ReadActions(f.Start).Actors[0].ActiveCooldownRemainingTicks);Assert.AreEqual(duration,node.Automation.Actors[0].ActiveCooldownRemainingTimeSpanTicks);Assert.AreEqual(before,f.Response.ToString());Assert.IsFalse(node.CanStart);}
 [TestCase(40000000L,40000000L,500000L)][TestCase(500001L,1L,500000L)][TestCase(1L,0L,500000L)][TestCase(40000000L,80L,250000L)][TestCase(40000000L,80L,0L)][TestCase(40000000L,80L,500001L)]
 public void RawDurationEarlyReadinessAndWrongClockCannotBecomeNodeActions(long duration,long steps,long step){var f=NodeWithDuration(duration,steps,step);Assert.Throws<ArgumentException>(()=>BRouteCommandResult.Read(200,f.Response.ToString(),f.Command));}
 [Test] public void SyntheticCompletionRoundtripKeepsQuantizedStepAndRestartDoesNotReconvert(){var first=NodeWithDuration(1,1);var initial=BRouteCommandResult.Read(200,first.Response.ToString(),first.Command).NodeStart;Assert.AreEqual(1,initial.ReadActions(first.Start).Actors[0].ActiveCooldownRemainingTicks);var automation=Automation(first.Start);foreach(JObject actor in (JArray)automation["actors"])actor["activeCooldownRemainingTicks"]=500000;var request=new OrdinaryNodeCompletion(first.Start.AccountId,first.Start.RunId,"quantized","node","synthetic-proof",3);var completion=Completion(request.Key,3,automation);var completed=request.ReadAutomation(completion.ToString(),first.Start);Assert.AreEqual(500000,completed.Actors[0].ActiveCooldownRemainingTimeSpanTicks);for(int i=0;i<2;i++){var f=NodeWithDuration(completed.Actors[0].ActiveCooldownRemainingTimeSpanTicks,1);var node=BRouteCommandResult.Read(200,f.Response.ToString(),f.Command).NodeStart;Assert.AreEqual(1,node.ReadActions(f.Start).Actors[0].ActiveCooldownRemainingTicks);var restart=new OrdinaryNodeRestart(node,"unit-restart",node.EntryMapRevision,1);var response=new JObject{["accepted"]=true,["version"]="ordinary.node-restart.v1.20261028",["requestId"]=restart.Key,["accountId"]=node.AccountId,["runId"]=node.RunId,["nodeId"]=node.NodeId,["status"]="RESTARTED",["revision"]=node.EntryMapRevision+1,["generation"]=2,["snapshot"]=node.Capture()["snapshot"],["snapshotHash"]=node.SnapshotHash};var restored=restart.ReadResponse(response.ToString()).Start;Assert.AreSame(node,restored);Assert.AreEqual(1,restored.ReadActions(f.Start).Actors[0].ActiveCooldownRemainingTicks);}}
 [TestCase("auto")][TestCase("charge")][TestCase("foreign")][TestCase("null")]
 public void NodeAutomationCannotDivergeFromOriginalRosterOrActionSettings(string fault){var f=OrdinaryNodeStartWireTests.Fixture();var node=f.Response["receipt"]["nodeStart"];node["snapshot"]["automation"]=Automation(f.Start);var actions=OrdinaryNodeActionsTests.Fixture(f.Start);actions["ultimateAuto"]=true;actions["stepTimeSpanTicks"]=500000;foreach(JObject actor in (JArray)actions["actors"]){actor["ultimateCharge"]=70;actor["activeCooldownRemainingTicks"]=80;}node["snapshot"]["runtime"]["actions"]=actions;if(fault=="auto")actions["ultimateAuto"]=false;if(fault=="charge")actions["actors"][0]["ultimateCharge"]=69;if(fault=="foreign")node["snapshot"]["automation"]["actors"][0]["operatorId"]="foreign";if(fault=="null")node["snapshot"]["automation"]=null;node["snapshotHash"]=BDirectAttackInput.Digest(node["snapshot"]).Substring(7);Assert.Throws<ArgumentException>(()=>BRouteCommandResult.Read(200,f.Response.ToString(),f.Command));}
 [Test] public void ChargeTwoHundredAndMaximumSafeDurationArePreservedWithoutClaimingO11Eligibility(){var f=FirstPlayableScalingTests.Fixture(staticSource:true);var start=OrdinaryFiveStartInput.Read(f.Start,"a",(string)f.Start["runId"]);var a=Automation(start);a["actors"][0]["ultimateCharge"]=200;a["actors"][0]["activeCooldownRemainingTicks"]=9007199254740991L;f.Init["initializationReceipt"]["ordinaryAutomation"]=a;var actor=((IEnumerable)Get(ReadInitial(f.Init,start),"Actors")).Cast<object>().First();Assert.AreEqual(200,Get(actor,"UltimateCharge"));Assert.AreEqual(9007199254740991L,Get(actor,"ActiveCooldownRemainingTimeSpanTicks"));}
 [Test] public async Task DedicatedCompletionPersistsOriginalResponseAndBindsRosterOnConsumption(){var f=OrdinaryNodeStartWireTests.Fixture();var command=new OrdinaryNodeCompletion(f.Start.AccountId,f.Start.RunId,"done","node","proof",3);var response=Completion("done",3,Automation(f.Start));var wire=new RunRiskBindingTests.Wire{Reply=r=>Task.FromResult(RunApiHttpResponse.Success(200,response.ToString()))};using var client=new DurableRunClient(new GameApiAuthenticatedHttpTransport(wire),new EncryptedRunOperationJournal(new Storage()),()=>RunRiskBindingTests.Session(f.Start.AccountId),()=>1,()=>new AppBuildSnapshot("automation-test",1));var pending=await client.CompleteOrdinaryNodeAsync(command);Assert.NotNull(pending,"Supplied automation receipt must survive durable validation");Assert.AreEqual(response.ToString(),pending.AcceptedResponseJson);var method=typeof(OrdinaryNodeCompletion).GetMethod("ReadAutomation");Assert.NotNull(method);var state=method.Invoke(command,new object[]{pending.AcceptedResponseJson,f.Start});Assert.AreEqual(true,Get(state,"UltimateAuto"));response["receipt"]["ordinaryAutomation"]["actors"][0]["operatorId"]="foreign";var error=Assert.Throws<TargetInvocationException>(()=>method.Invoke(command,new object[]{response.ToString(),f.Start}));Assert.IsInstanceOf<ArgumentException>(error.InnerException);}
 [Test] public void BRouteCompletionRetainsAutomationAlongsideOriginalReceipt(){var f=OrdinaryNodeStartWireTests.Fixture();var route=f.Command.Binding.Capture();route["phase"]="ACTIVE";route["currentNode"]=route["pendingNode"].DeepClone();route["pendingNode"]=null;route["pendingEdgeId"]=null;route.Remove("packetHash");route["packetHash"]=BDirectAttackInput.Digest(route).Substring(7);var binding=BRouteBinding.Read(route.ToString(),(string)route["packetHash"],f.Start.AccountId,f.Start.RunId);var command=BRouteCommand.FromOriginal(binding,new JObject{["kind"]="COMPLETE",["eventId"]="done",["expectedRevision"]=binding.MapRevision,["nodeId"]=route["currentNode"]["nodeId"].DeepClone(),["evidenceRef"]="proof"});var response=Completion("done",binding.MapRevision,Automation(f.Start));var root=new JObject{["version"]=BRouteBinding.Version,["committed"]=true,["receipt"]=response["receipt"]};var result=BRouteCommandResult.Read(200,root.ToString(),command);Assert.AreEqual(true,Get(Get(result,"OrdinaryAutomation"),"UltimateAuto"));Assert.IsTrue(JToken.DeepEquals(root,result.Capture()));}
}
